export async function createApplication(
  config: Config,
  options: ApplicationOptions = {},
): Promise<Application> {
  if (options.verifyRpc !== false) await verifyRpcChain(config.rpcUrl);
  const ownsDatabase = options.db === undefined;
  const db = options.db ?? openDatabase(config.databasePath);
  let wallet: WalletService;
  try {
    wallet = WalletService.provision(
      db,
      config.walletEncryptionKey,
      config.walletMnemonic,
      config.walletPassphrase,
    );
  } catch (error) {
    if (ownsDatabase) db.close();
    throw error;
  }
  const auth = new AuthService(db, wallet, config.sessionTtlSeconds, options.now);
  const limits = options.rateLimits ?? new RateLimitService();
  const app = Fastify({ logger: false, exposeHeadRoutes: false });
  await app.register(fastifyWebsocket, { options: { maxPayload: 64 * 1024 } });
  const loginPrechecks = new WeakMap<FastifyRequest, RateLimitDecision>();

  // The React client is served from a different origin during development and in a
  // typical deployment. Authentication uses an explicit Bearer header (never cookies),
  // so a wildcard origin is safe here while the requested headers must be explicit for
  // browser preflight checks.
  app.addHook("onRequest", (_request, reply, done) => {
    reply.header("Access-Control-Allow-Origin", "*");
    reply.header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS");
    reply.header("Access-Control-Allow-Headers", "Authorization, Content-Type");
    reply.header("Access-Control-Max-Age", "600");
    done();
  });

  // Keep parsing after the onRequest rate-limit step. This preserves the required
  // rate-limit > schema precedence while still allowing every failed login to be audited.
  app.removeContentTypeParser("application/json");
  app.addContentTypeParser("application/json", { parseAs: "string" }, (_request, body, done) => {
    done(null, body);
  });
  app.addContentTypeParser("*", { parseAs: "string" }, (_request, body, done) => {
    done(null, body);
  });

  if (ownsDatabase) {
    app.addHook("onClose", async () => db.close());
  }

  app.setErrorHandler((cause, request, reply) => {
    let error: AppError;
    if (cause instanceof AppError) {
      error = cause;
    } else if (isBodyTooLargeError(cause)) {
      const routingError = requestRoutingError(request);
      if (routingError) return sendRoutingError(reply, routingError);

      if (request.method === "POST" && requestPath(request) === "/api/v1/auth/login") {
        const precheck = loginPrechecks.get(request) ?? limits.precheckLogin(request.ip);
        if (!precheck.allowed) {
          // Fastify does not expose a body after rejecting its stream, so the attempt
          // cannot be attributed to a trustworthy normalized email.
          auth.writeAudit("", "FAILURE", "RATE_LIMITED", request.ip);
          return enforceLimit(reply, precheck);
        }
        // A body rejected by Fastify never reaches the login handler. It is still a
        // failed authentication attempt for rate-limit and audit purposes. Since the
        // rejected stream is unavailable, no purported email can be trusted/extracted.
        auth.writeAudit("", "FAILURE", "VALIDATION_ERROR", request.ip);
        limits.recordLoginFailure(request.ip);
      } else if (
        request.method === "GET" &&
        requestPath(request) === "/api/v1/deposit-address"
      ) {
        // Authentication and the per-account limit precede input validation on protected
        // resources, including validation performed after a parser-size rejection.
        let accountId: string;
        try {
          accountId = auth.authenticate(request.headers.authorization);
        } catch (authenticationError) {
          if (authenticationError instanceof AppError) {
            return sendAppError(reply, authenticationError);
          }
          return sendAppError(reply, new AppError("INTERNAL_ERROR", "Ocurrió un error interno."));
        }
        const decision = limits.consumeProtected(accountId, "/api/v1/deposit-address");
        if (!decision.allowed) return enforceLimit(reply, decision);
      }

      error = validationIssue("body", "El cuerpo excede el tamaño permitido");
    } else if (isFrameworkValidationError(cause)) {
      error = validationIssue("body", "El cuerpo debe ser JSON válido con Content-Type application/json");
    } else {
      error = new AppError("INTERNAL_ERROR", "Ocurrió un error interno.");
    }
    sendAppError(reply, error);
  });

  app.setNotFoundHandler((request, reply) => {
    const routingError = requestRoutingError(request);
    return sendRoutingError(
      reply,
      routingError ?? new AppError("NOT_FOUND", "El recurso solicitado no existe."),
    );
  });

  app.get("/health", async () => ({ status: "ok" }));

  app.get("/api/v1/ws", { websocket: true }, (socket) => {
    attachWebSocketSession(socket, auth, {
      authTimeoutMs: options.wsAuthTimeoutMs,
      heartbeatIntervalMs: options.wsHeartbeatIntervalMs,
      pongTimeoutMs: options.wsPongTimeoutMs,
      now: options.now,
    });
  });

  app.options("/api/v1/auth/login", async (request, reply) =>
    sendCorsPreflight(request, reply, "POST"),
  );
  app.options("/api/v1/me", async (request, reply) =>
    sendCorsPreflight(request, reply, "GET"),
  );

  app.post(
    "/api/v1/auth/register",
    { onRequest: async (request, reply) => enforceLimit(reply, limits.consumeRegister(request.ip)) },
    async (request, reply) => {
      const body = parseRegisterBody(parseJsonRequestBody(request));
      const account = await auth.register(body.email, body.password);
      return reply.code(201).send(account);
    },
  );

  app.post(
    "/api/v1/auth/login",
    {
      onRequest: async (request) => {
        const precheck = limits.precheckLogin(request.ip);
        loginPrechecks.set(request, precheck);
      },
    },
    async (request, reply) => {
      const precheck = loginPrechecks.get(request)!;
      if (!precheck.allowed) {
        const email = bestEffortEmail(request.body);
        auth.writeAudit(email, "FAILURE", "RATE_LIMITED", request.ip);
        enforceLimit(reply, precheck);
        return;
      }
      let body: { email: string; password: string };
      try {
        body = parseLoginBody(parseJsonRequestBody(request));
      } catch (error) {
        const raw = bestEffortEmail(request.body);
        auth.writeAudit(raw, "FAILURE", "VALIDATION_ERROR", request.ip);
        limits.recordLoginFailure(request.ip);
        throw error;
      }
      const result = await auth.login(body.email, body.password, request.ip);
      if (!result) {
        limits.recordLoginFailure(request.ip);
        throw new AppError("INVALID_CREDENTIALS", "Las credenciales son inválidas.");
      }
      return reply.code(200).send(result);
    },
  );

  app.post("/api/v1/auth/logout", async (request, reply) => {
    const accountId = auth.authenticate(request.headers.authorization);
    enforceLimit(reply, limits.consumeProtected(accountId, "/api/v1/auth/logout"));
    if (reply.sent) return;
    auth.logout(request.headers.authorization);
    return reply.code(204).send();
  });

  app.get("/api/v1/me", async (request, reply) => {
    const accountId = auth.authenticate(request.headers.authorization);
    enforceLimit(reply, limits.consumeProtected(accountId, "/api/v1/me"));
    if (reply.sent) return;
    return reply.code(200).send(auth.getAccount(accountId));
  });

  app.get("/api/v1/deposit-address", async (request, reply) => {
    const accountId = auth.authenticate(request.headers.authorization);
    enforceLimit(reply, limits.consumeProtected(accountId, "/api/v1/deposit-address"));
    if (reply.sent) return;

    const query = isRecord(request.query) ? request.query : {};
    const assetValues = queryValues(query.asset);
    if (assetValues.length !== 1 || (assetValues[0] !== "ETH" && assetValues[0] !== "USDC")) {
      throw validationIssue("asset", "El activo debe ser ETH o USDC");
    }
    const networkValues = queryValues(query.network);
    const chainIdValues = queryValues(query.chainId);
    const invalidNetwork = networkValues.find((value) => value.toLowerCase() !== "sepolia");
    const invalidChainId = chainIdValues.find((value) => value !== CHAIN_ID);
    const invalidNetworkValue = invalidNetwork ?? invalidChainId;
    if (invalidNetworkValue !== undefined) {
      throw new AppError("CHAIN_ID_MISMATCH", "La única red soportada es Sepolia.", {
        expected: CHAIN_ID,
        got: invalidNetworkValue,
      });
    }

    const assigned = wallet.getOrAssign(accountId);
    const response: Record<string, string> = {
      asset: assetValues[0],
      address: assigned.address,
      network: assigned.network,
      chainId: assigned.chainId,
    };
    if (assetValues[0] === "USDC") response.tokenAddress = config.usdcTokenAddress;
    return reply.code(200).send(response);
  });

  return { app, db, auth, wallet };
}

function parseRegisterBody(body: unknown): { email: string; password: string } {
  if (!isRecord(body)) throw validationIssue("body", "Debe ser un objeto JSON");
  const keys = Object.keys(body);
  const unknown = keys.find((key) => key !== "email" && key !== "password");
  if (unknown) throw validationIssue(unknown, "Campo desconocido");
  if (!("email" in body)) throw validationIssue("email", "Campo requerido");
  if (!("password" in body)) throw validationIssue("password", "Campo requerido");
  if (typeof body.email !== "string") throw validationIssue("email", "Debe ser string");
  if (typeof body.password !== "string") throw validationIssue("password", "Debe ser string");
  return { email: body.email, password: body.password };
}

function parseLoginBody(body: unknown): { email: string; password: string } {
  if (!isRecord(body)) throw validationIssue("body", "Debe ser un objeto JSON");
  if (!("email" in body)) throw validationIssue("email", "Campo requerido");
  if (!("password" in body)) throw validationIssue("password", "Campo requerido");
  if (typeof body.email !== "string") throw validationIssue("email", "Debe ser string");
  if (typeof body.password !== "string") throw validationIssue("password", "Debe ser string");
  return { email: body.email, password: body.password };
}

function parseJsonBody(body: unknown): unknown {
  if (typeof body !== "string") return body;
  try {
    return JSON.parse(body) as unknown;
  } catch {
    throw validationIssue("body", "El cuerpo debe ser JSON válido");
  }
}

function parseJsonRequestBody(request: FastifyRequest): unknown {
  const contentType = request.headers["content-type"]?.split(";", 1)[0]?.trim().toLowerCase();
  if (contentType !== "application/json") {
    throw validationIssue("content-type", "Debe ser application/json");
  }
  return parseJsonBody(request.body);
}

function bestEffortEmail(body: unknown): string {
  try {
    const parsed = parseJsonBody(body);
    return isRecord(parsed) && typeof parsed.email === "string" ? normalizeEmail(parsed.email) : "";
  } catch {
    return "";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function queryValues(value: unknown): string[] {
  if (typeof value === "string") return [value];
  if (Array.isArray(value) && value.every((item) => typeof item === "string")) return value;
  return [];
}

function isFrameworkValidationError(cause: unknown): boolean {
  if (typeof cause !== "object" || cause === null) return false;
  const candidate = cause as { code?: unknown; statusCode?: unknown };
  return (
    candidate.code === "FST_ERR_CTP_INVALID_JSON_BODY" ||
    candidate.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
    candidate.statusCode === 400 ||
    candidate.statusCode === 415
  );
}

function isBodyTooLargeError(cause: unknown): boolean {
  return (
    typeof cause === "object" &&
    cause !== null &&
    "code" in cause &&
    cause.code === "FST_ERR_CTP_BODY_TOO_LARGE"
  );
}

function requestPath(request: FastifyRequest): string {
  return request.url.split("?", 1)[0];
}

function requestRoutingError(request: FastifyRequest): AppError | undefined {
  const allowed = KNOWN_ROUTES.get(requestPath(request));
  if (allowed === undefined) {
    return new AppError("NOT_FOUND", "El recurso solicitado no existe.");
  }
  if (!allowed.includes(request.method)) {
    return new AppError("METHOD_NOT_ALLOWED", "El método no está permitido para esta ruta.", {
      method: request.method,
      allowed,
    });
  }
  return undefined;
}

function sendCorsPreflight(
  request: FastifyRequest,
  reply: FastifyReply,
  allowedMethod: string,
): FastifyReply {
  const origin = request.headers.origin;
  const requestedMethod = request.headers["access-control-request-method"];
  if (
    typeof origin === "string" &&
    origin.trim().length > 0 &&
    requestedMethod === allowedMethod
  ) {
    return reply.code(204).send();
  }

  return sendRoutingError(
    reply,
    new AppError("METHOD_NOT_ALLOWED", "El método no está permitido para esta ruta.", {
      method: request.method,
      allowed: [allowedMethod],
    }),
  );
}

function enforceLimit(
  reply: FastifyReply,
  decision: RateLimitDecision,
): FastifyReply | undefined {
  if (decision.allowed) return undefined;
  const error = new AppError("RATE_LIMITED", "Se superó el límite de solicitudes.", {
    retryAfterSeconds: decision.retryAfterSeconds,
  });
  reply.header("Retry-After", String(decision.retryAfterSeconds));
  return sendAppError(reply, error);
}

function sendAppError(reply: FastifyReply, error: AppError): FastifyReply {
  if (error.code === "RATE_LIMITED" && error.details) {
    reply.header("Retry-After", String(error.details.retryAfterSeconds));
  }
  return reply.code(error.status).send(errorBody(error));
}

function sendRoutingError(reply: FastifyReply, error: AppError): FastifyReply {
  if (error.code === "METHOD_NOT_ALLOWED") {
    const allowed = error.details!.allowed as string[];
    reply.header("Allow", allowed.join(", "));
  }
  return sendAppError(reply, error);
}

