  const value = env[name]?.trim();
20→  if (!value) throw new Error(`Configuración inválida: falta ${name}`);
  return value;
}

function encryptionKey(raw: string): Buffer {
  let key: Buffer;
  if (/^[0-9a-fA-F]{64}$/.test(raw)) key = Buffer.from(raw, "hex");
  else key = Buffer.from(raw, "base64");
  if (key.length !== 32) {
    throw new Error("Configuración inválida: WALLET_ENCRYPTION_KEY debe contener 32 bytes");
30→  }
  return key;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const ttlRaw = env.SESSION_TTL_SECONDS ?? "3600";
  if (!/^[0-9]+$/.test(ttlRaw)) {
    throw new Error("Configuración inválida: SESSION_TTL_SECONDS debe ser entero");
  }
  const sessionTtlSeconds = Number(ttlRaw);
40→  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86_400) {
    throw new Error("Configuración inválida: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
  }

  const portRaw = env.PORT ?? "3000";
  if (!/^[0-9]+$/.test(portRaw) || Number(portRaw) < 1 || Number(portRaw) > 65_535) {
    throw new Error("Configuración inválida: PORT debe estar entre 1 y 65535");
  }

  const addressRaw = required(env, "USDC_TOKEN_ADDRESS");
50→  let usdcTokenAddress: string;
  try {
    usdcTokenAddress = getAddress(addressRaw);
  } catch {
    throw new Error("Configuración inválida: USDC_TOKEN_ADDRESS no es una dirección EIP-55 válida");
  }
  // If callers supplied letters in mixed case, ethers verifies their checksum. All-lowercase
  // is accepted as input and normalized to the required EIP-55 output.

  const rpcUrl = required(env, "RPC_URL");
60→  try {
    const parsed = new URL(rpcUrl);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") throw new Error();
  } catch {
    throw new Error("Configuración inválida: RPC_URL debe ser una URL HTTP(S)");
  }

  return {
    host: env.HOST?.trim() || "0.0.0.0",
    port: Number(portRaw),
70→    databasePath: resolve(env.DATABASE_PATH?.trim() || "./data/exchange.sqlite"),
    sessionTtlSeconds,
    walletEncryptionKey: encryptionKey(required(env, "WALLET_ENCRYPTION_KEY")),
    usdcTokenAddress,
    rpcUrl,
    walletMnemonic: env.WALLET_MNEMONIC?.trim() || undefined,
    walletPassphrase: env.WALLET_PASSPHRASE ?? "",
  };
}

