  generateProvisioningMnemonic,
  MAX_ADDRESS_INDEX,
  toChecksumAddress,
  validateAddressIndex,
  validateProvisioningMnemonic,
  WALLET_SEED_BYTES,
  WalletCryptoError,
} from "../src/wallet/crypto.js";

const MNEMONIC_BIP39_CANONICO =
  "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const MNEMONIC_HARDHAT = "test test test test test test test test test test test junk";

describe("BIP-39", () => {
  it("reproduce el known-answer test PBKDF2-HMAC-SHA512", () => {
    const seed = deriveBip39Seed(MNEMONIC_BIP39_CANONICO, "TREZOR");
    assert.equal(
      Buffer.from(seed).toString("hex"),
      "c55257c360c07c72029aebc1b53c05ed0362ada38ead3e3e9efa3708e53495531f09a6987599d18264c1e1c92f2cf141630c7a3c4ab7c81b2f001698e7463b04",
    );
    assert.equal(seed.byteLength, 64);
  });

  it("es determinístico y aplica NFKD a la passphrase", () => {
    const composed = deriveBip39Seed(MNEMONIC_BIP39_CANONICO, "é");
    const decomposed = deriveBip39Seed(MNEMONIC_BIP39_CANONICO, "e\u0301");
    assert.deepEqual(composed, decomposed);
  });

  it("genera un mnemonic de 24 palabras desde exactamente 256 bits", () => {
    const phrase = generateProvisioningMnemonic((length) => {
      assert.equal(length, 32);
      return new Uint8Array(32);
    });
    assert.equal(phrase.split(" ").length, 24);
    assert.equal(validateProvisioningMnemonic(phrase), phrase);
  });

  it("usa un CSPRNG por generación y no una entropía fija", () => {
    const first = generateProvisioningMnemonic();
    const second = generateProvisioningMnemonic();
    assert.notEqual(first, second);
    assert.equal(first.split(" ").length, 24);
    assert.equal(second.split(" ").length, 24);
  });

  it("rechaza primero longitud, luego wordlist y luego checksum", () => {
    assert.throws(
      () => validateProvisioningMnemonic(MNEMONIC_BIP39_CANONICO),
      (error: unknown) => error instanceof WalletCryptoError &&
        error.code === "VALIDATION_ERROR" && /24 palabras/.test(error.message),
    );

    const valid24 = generateProvisioningMnemonic(() => new Uint8Array(32));
    const outsideWordlist = valid24.split(" ");
    outsideWordlist[7] = "palabra-inexistente";
    assert.throws(
      () => validateProvisioningMnemonic(outsideWordlist.join(" ")),
      (error: unknown) => error instanceof WalletCryptoError && /wordlist/.test(error.message),
    );

    assert.throws(
      () => validateProvisioningMnemonic(Array(24).fill("abandon").join(" ")),
      (error: unknown) => error instanceof WalletCryptoError && /checksum/.test(error.message),
    );
  });
});

describe("custodia AES-256-GCM", () => {
  const seed = deriveBip39Seed(MNEMONIC_HARDHAT);
  const key = new Uint8Array(32).fill(0x42);
  const nonce = new Uint8Array(12).fill(0x17);

  it("serializa exactamente nonce || ciphertext || tag y descifra", () => {
    const envelope = encryptSeed(seed, key, (length) => {
      assert.equal(length, AES_GCM_NONCE_BYTES);
      return nonce;
    });

    assert.equal(envelope.byteLength, AES_GCM_NONCE_BYTES + WALLET_SEED_BYTES + AES_GCM_TAG_BYTES);
    assert.deepEqual(envelope.slice(0, AES_GCM_NONCE_BYTES), nonce);
    assert.notDeepEqual(
      envelope.slice(AES_GCM_NONCE_BYTES, AES_GCM_NONCE_BYTES + WALLET_SEED_BYTES),
      seed,
    );
    assert.deepEqual(decryptSeed(envelope, key), seed);
  });

  it("pide un nonce nuevo en cada cifrado", () => {
    let calls = 0;
    const randomSource = () => new Uint8Array(12).fill(++calls);
    const first = encryptSeed(seed, key, randomSource);
    const second = encryptSeed(seed, key, randomSource);
    assert.equal(calls, 2);
    assert.notDeepEqual(first.slice(0, 12), second.slice(0, 12));
  });

  it("rechaza credenciales incorrectas y tags corruptos sin filtrar secretos", () => {
    const envelope = encryptSeed(seed, key, () => nonce);
    const wrongKey = new Uint8Array(32).fill(0x43);
    assert.throws(
      () => decryptSeed(envelope, wrongKey),
      (error: unknown) => error instanceof WalletCryptoError && error.code === "INTERNAL_ERROR",
    );

    const corrupted = envelope.slice();
    corrupted[corrupted.length - 1] ^= 1;
    assert.throws(
      () => decryptSeed(corrupted, key),
      (error: unknown) => error instanceof WalletCryptoError &&
        error.code === "INTERNAL_ERROR" && !error.message.includes(Buffer.from(seed).toString("hex")),
    );
  });
});

describe("BIP-32/BIP-44 y direcciones Ethereum", () => {
  const seed = deriveBip39Seed(MNEMONIC_HARDHAT);

  it("reproduce los cuatro vectores Hardhat/Anvil", () => {
