    assert.match(deriveEthereumAddress(seed, MAX_ADDRESS_INDEX), /^0x[0-9a-fA-F]{40}$/);
    for (const invalid of [-1, 1.5, MAX_ADDRESS_INDEX + 1]) {
      assert.throws(
        () => validateAddressIndex(invalid),
        (error: unknown) => error instanceof WalletCryptoError &&
          error.code === "VALIDATION_ERROR" && error.issues?.[0]?.field === "address_index",
      );
    }
  });

  const derivationLevels = [
    { name: "purpose", initialIndex: 44 + 0x80000000, expectedPath: "m/45'/60'/0'/0/7", expectedAddressIndex: 7 },
    { name: "coin type", initialIndex: 60 + 0x80000000, expectedPath: "m/44'/61'/0'/0/7", expectedAddressIndex: 7 },
    { name: "account", initialIndex: 0x80000000, expectedPath: "m/44'/60'/1'/0/7", expectedAddressIndex: 7 },
    { name: "change", initialIndex: 0, expectedPath: "m/44'/60'/0'/1/7", expectedAddressIndex: 7 },
    { name: "address index", initialIndex: 7, expectedPath: "m/44'/60'/0'/0/8", expectedAddressIndex: 8 },
  ] as const;

  const invalidConditions = ["I_L >= n", "k_hijo == 0"] as const;

  for (const [targetLevel, level] of derivationLevels.entries()) {
    for (const condition of invalidConditions) {
      it(`reintenta ${level.name} en el mismo nivel ante ${condition}`, () => {
        const firstInjection = invalidChildHmac(targetLevel, condition);
        const result = deriveEthereumKey(seed, 7, firstInjection.hmac);

        assert.deepEqual(firstInjection.attemptedIndices, [level.initialIndex, level.initialIndex + 1]);
        assert.equal(result.addressIndex, level.expectedAddressIndex);
        assert.equal(result.derivationPath, level.expectedPath);
