function invalidChildHmac(
  targetLevel: number,
  condition: "I_L >= n" | "k_hijo == 0",
): {
  hmac: (key: Uint8Array, data: Uint8Array) => Uint8Array;
  attemptedIndices: number[];
  targetKeys: Buffer[];
  targetDataPrefixes: Buffer[];
