import { CHAIN_ID } from "./config.js";
import { AppError } from "./errors.js";

interface JsonRpcResponse {
  result?: unknown;
  error?: unknown;
}

export async function verifyRpcChain(rpcUrl: string): Promise<void> {
  let response: Response;
  try {
    response = await fetch(rpcUrl, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", method: "eth_chainId", params: [], id: 1 }),
      signal: AbortSignal.timeout(5_000),
    });
  } catch {
    throw new AppError("INTERNAL_ERROR", "No se pudo contactar el nodo JSON-RPC configurado.");
  }
  if (!response.ok) {
    throw new AppError("INTERNAL_ERROR", "El nodo JSON-RPC configurado rechazó la consulta.");
  }
  let payload: JsonRpcResponse;
  try {
    payload = (await response.json()) as JsonRpcResponse;
  } catch {
    throw new AppError("INTERNAL_ERROR", "El nodo JSON-RPC devolvió una respuesta inválida.");
  }
  if (typeof payload.result !== "string" || !/^0x[0-9a-fA-F]+$/.test(payload.result)) {
    throw new AppError("INTERNAL_ERROR", "El nodo JSON-RPC no devolvió un chainId válido.");
  }
  const got = BigInt(payload.result).toString(10);
  if (got !== CHAIN_ID) {
    throw new AppError("CHAIN_ID_MISMATCH", "El nodo no corresponde a Sepolia.", {
      expected: CHAIN_ID,
      got,
    });
  }
}

