  const candidate = await derivePassword(password, comparisonTarget.salt);
110→  const matches = timingSafeEqual(candidate, comparisonTarget.derivedKey);

  return parsed !== null && matches;
}

/** Generate an opaque session token with 256 bits of operating-system CSPRNG entropy. */
export function generateOpaqueToken(): string {
  return randomBytes(32).toString("base64url");
}

120→/** Produce the one-way value persisted for a high-entropy opaque session token. */
export function hashOpaqueToken(token: string): string {
  return `sha256$${createHash("sha256").update(token, "utf8").digest("base64url")}`;
}

/** Apply the sole identity normalization allowed by HU-01-01: trim plus lowercase. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

130→export const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;

/** Validate the normalized email against the exact project regex and 254-char limit. */
export function isValidEmail(email: string): boolean {
  const normalized = normalizeEmail(email);
  return Array.from(normalized).length <= 254 && EMAIL_PATTERN.test(normalized);
}

