import assert from "node:assert/strict";
import { randomBytes } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, test } from "node:test";
import type { Config } from "../src/config.js";
import { createApplication, type Application } from "../src/app.js";
import { openDatabase } from "../src/database.js";
import { RateLimitService } from "../src/rate-limit.js";

const applications: Application[] = [];
const tempDirectories: string[] = [];

function config(databasePath = ":memory:", key = randomBytes(32)): Config {
  return {
    host: "127.0.0.1",
    port: 3000,
    databasePath,
    sessionTtlSeconds: 3600,
    walletEncryptionKey: key,
    usdcTokenAddress: "0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed",
    rpcUrl: "http://127.0.0.1:1",
    walletPassphrase: "",
  };
}

async function application(
  appConfig = config(),
  rateLimits?: RateLimitService,
): Promise<Application> {
  const db = openDatabase(appConfig.databasePath);
  const result = await createApplication(appConfig, { db, verifyRpc: false, rateLimits });
  applications.push(result);
  return result;
}

afterEach(async () => {
  while (applications.length) {
    const current = applications.pop()!;
    await current.app.close();
    current.db.close();
  }
  while (tempDirectories.length) rmSync(tempDirectories.pop()!, { recursive: true, force: true });
});

async function register(app: Application, email = "trader@example.com", password = "Sup3rSecreta") {
  return app.app.inject({
    method: "POST",
    url: "/api/v1/auth/register",
    headers: { "content-type": "application/json" },
    payload: { email, password },
  });
}

async function login(app: Application, email = "trader@example.com", password = "Sup3rSecreta") {
  return app.app.inject({
    method: "POST",
    url: "/api/v1/auth/login",
    headers: { "content-type": "application/json" },
    payload: { email, password },
  });
}

async function logout(app: Application, token?: string) {
  return app.app.inject({
    method: "POST",
    url: "/api/v1/auth/logout",
    headers: token === undefined ? undefined : { authorization: `Bearer ${token}` },
  });
}

