import { createHash } from "node:crypto";
import { Mnemonic, wordlists } from "ethers";
import { deriveBip39Seed } from "/tmp/eval-wb/eval-p2-sut/src/wallet/crypto.ts";

const mode = process.argv[2] ?? "kat-06-01-02";

if (mode === "kat-06-01-02") {
  const mnemonic =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
  const seed = deriveBip39Seed(mnemonic, "TREZOR");
  process.stdout.write(`${Buffer.from(seed).toString("hex")}\n`);
} else if (mode === "kat-06-01-03") {
  const mnemonic = `${"abandon ".repeat(23)}art`;
  const seed = deriveBip39Seed(mnemonic, "");
  process.stdout.write(`${Buffer.from(seed).toString("hex")}\n`);
} else if (mode === "mnemonic-24") {
  const entropy = Buffer.alloc(32, 0);
  const checksumBits = createHash("sha256").update(entropy).digest()[0];
  const phrase = Mnemonic.entropyToPhrase(entropy, wordlists.en);
  process.stdout.write(`phrase=${phrase}\n`);
  process.stdout.write(`sha256_first_byte=${checksumBits.toString(16).padStart(2, "0")}\n`);
  process.stdout.write(`word_count=${phrase.split(" ").length}\n`);
} else {
  process.stderr.write(`unknown mode ${mode}\n`);
  process.exit(2);
}

