import { createHash, readFileSync } from "node:fs";
import { createHash as sha } from "node:crypto";
import { readFileSync as read } from "node:fs";

const wordlist = read(
  "/private/tmp/eval-wb-pre-piloto-2b-p2-20260907-134323/corpus/documentos/bip-0039-wordlist-english.txt",
  "utf8",
)
  .trim()
  .split("\n");

const entropy = Buffer.alloc(32, 0);
const hash = sha("sha256").update(entropy).digest();
const checksumLen = 8;
const bits: number[] = [];
for (const byte of entropy) {
  for (let i = 7; i >= 0; i--) bits.push((byte >> i) & 1);
}
for (let i = 7; i >= 8 - checksumLen; i--) bits.push((hash[0] >> i) & 1);

const words: string[] = [];
for (let w = 0; w < 24; w++) {
  let idx = 0;
  for (let i = 0; i < 11; i++) idx = (idx << 1) | bits[w * 11 + i]!;
  words.push(wordlist[idx]!);
}

process.stdout.write(`sha256=${hash.toString("hex")}\n`);
process.stdout.write(`phrase=${words.join(" ")}\n`);
process.stdout.write(`last_word=${words[23]}\n`);
process.stdout.write(`wordlist_len=${wordlist.length}\n`);

