def yaml_quote(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def dump_item(item: dict) -> str:
    lines = [f"  - at_id: {item['at_id']}", f"    veredicto: {item['veredicto']}"]
    if item["veredicto"] == "NO_EVALUABLE":
        lines.append(f"    causa: {item['causa']}")
    lines.append("    evidencia:")
    for ev in item["evidencia"]:
        lines.append("      - tipo: " + ev["tipo"])
        lines.append("        ref: " + yaml_quote(ev["ref"]))
        lines.append("        detalle: " + yaml_quote(ev["detalle"]))
    just = " ".join(item["justificacion"].split())
    lines.append("    justificacion: >-")
    # wrap ~100 chars
    words = just.split()
    buf = ""
    chunks = []
    for w in words:
        if not buf:
            buf = w
        elif len(buf) + 1 + len(w) > 100:
            chunks.append(buf)
            buf = w
        else:
            buf += " " + w
    if buf:
        chunks.append(buf)
    for c in chunks:
        lines.append("      " + c)
    lines.append(f"    duracion_min: {item['duracion_min']}")
    return "\n".join(lines)


